755:     int nth_tot = nth + 2 * NGHOST;
756:     int ncells = nr_tot * nth_tot * nph;
757: 
758:     double fr = (r_p - (r_in + 0.5 * dr)) / dr + NGHOST;
759:     int ir0 = std::max(NGHOST, std::min((int)std::floor(fr), nr + NGHOST - 2));
760:     int ir1 = ir0 + 1;
