768:     double fph = (ph_p - 0.5 * dph) / dph;
769:     int iph0 = ((int)std::floor(fph) % nph + nph) % nph;
770:     int iph1 = (iph0 + 1) % nph;
771:     double wph = fph - std::floor(fph);
772: 
773:     for (int m = 0; m < NVAR; ++m) W_out[m] = 0.0;
774: 
775:     for (int dr_i = 0; dr_i <= 1; ++dr_i) {
776:         double wt_r = (dr_i == 0) ? (1.0 - wr) : wr;
777:         int ir = (dr_i == 0) ? ir0 : ir1;
778:         for (int dth_i = 0; dth_i <= 1; ++dth_i) {
779:             double wt_th = (dth_i == 0) ? (1.0 - wth) : wth;
